<?php
namespace qqworld_collector\module\collect_filter; class string_to_array extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $type = isset($args['type']) ? $args['type'] : 'explode'; switch ($type) { case 'explode': $string = isset($args['string']) ? str_replace('&quot;', '"', $args['string']) : ','; if ($string) $item = explode($string, $item); break; case 'regex': $regex = isset($args['regex']) ? $args['regex'] : ''; if ($regex) $item = $GLOBALS['QC']->collector->engine->parse_html($item, $regex); break; } return $item; } } ?>